<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requireSuperAdmin();
$pdo=Database::connection();$id=(int)($_GET['id']??$_POST['id']??0);$notice='';$error='';
DanceCupScoringService::ensureWorkspaceTables($pdo,false);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');
  if(empty($_POST['review_confirmed']))throw new RuntimeException('Confirm that you reviewed the ranking, judge scores and private comments.');
  $pdo->beginTransaction();
  DanceCupScoringService::approveResults($pdo,$id,(int)(Auth::user()['id']??0),false,trim((string)($_POST['approval_notes']??''))?:null);
  $pdo->commit();$notice='Official Dance Cup result approved and published to permanent history.';
 }catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error=$exception->getMessage();}
}
$q=$pdo->prepare("SELECT c.*,e.name event_name,e.event_date FROM bdc_dance_cup_competitions c JOIN bdc_dance_cup_events e ON e.id=c.event_id WHERE c.id=:id");$q->execute(['id'=>$id]);$competition=$q->fetch();if(!$competition){http_response_code(404);exit('Dance Cup category not found.');}
$q=$pdo->prepare("SELECT * FROM bdc_dance_cup_criteria WHERE competition_id=:id ORDER BY sort_order,id");$q->execute(['id'=>$id]);$criteria=$q->fetchAll();
$q=$pdo->prepare("SELECT * FROM bdc_dance_cup_entries WHERE competition_id=:id AND status='active' ORDER BY bib_number,id");$q->execute(['id'=>$id]);$entries=$q->fetchAll();
$q=$pdo->prepare("SELECT * FROM bdc_dance_cup_judges WHERE competition_id=:id ORDER BY is_chief DESC,judge_order,id");$q->execute(['id'=>$id]);$judges=$q->fetchAll();
$q=$pdo->prepare("SELECT entry_id,judge_id,criterion_id,points FROM bdc_dance_cup_marks WHERE competition_id=:id");$q->execute(['id'=>$id]);$marks=[];foreach($q->fetchAll() as $row)$marks[(int)$row['entry_id']][(int)$row['judge_id']][(int)$row['criterion_id']]=(float)$row['points'];
$q=$pdo->prepare("SELECT entry_id,judge_id,private_comment FROM bdc_dance_cup_judge_comments WHERE competition_id=:id AND TRIM(private_comment)<>''");$q->execute(['id'=>$id]);$comments=[];foreach($q->fetchAll() as $row)$comments[(int)$row['entry_id']][(int)$row['judge_id']]=(string)$row['private_comment'];
$q=$pdo->prepare("SELECT r.*,e.bib_number,e.display_name FROM bdc_dance_cup_scoring_results r JOIN bdc_dance_cup_entries e ON e.id=r.entry_id WHERE r.competition_id=:id ORDER BY r.placement,e.bib_number");$q->execute(['id'=>$id]);$results=$q->fetchAll();
$csrf=Csrf::token();$pending=(string)$competition['status']==='pending_approval';
function dcReviewNumber(float $value):string{return rtrim(rtrim(number_format($value,2,'.',''),'0'),'.');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review Official Dance Cup Result</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=439" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=505"></script><style>.review-wrap{max-width:1500px}.result-card{border-left:5px solid #d4a72c}.judge-block{border:1px solid #dbe3ec;border-radius:12px;overflow:hidden}.judge-head{background:#14213d;color:#fff;padding:10px 14px}.comment{border-left:4px solid #9e244d;background:#fff3f7;padding:10px 12px;white-space:pre-wrap}.approval-dock{position:sticky;bottom:0;z-index:5;background:#fff;border-top:3px solid #198754;box-shadow:0 -8px 24px #17203322}@media(max-width:767px){.table{font-size:.82rem}.approval-dock .row>*{width:100%}}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="approvals.php">← Pending Approvals</a><span class="badge text-bg-warning">SUPER ADMIN CONFIDENTIAL REVIEW</span></div></nav><main class="container-fluid review-wrap py-4"><header class="mb-4"><span class="badge text-bg-<?=$pending?'warning':'success'?>"><?=e(strtoupper((string)$competition['status']))?></span><h1 class="h2 mt-2 mb-1"><?=e($competition['category_name'])?></h1><p class="text-muted mb-0"><?=e($competition['event_name'])?> · <?=e(ucwords(str_replace('_',' ',(string)$competition['dance_style'])))?> · <?=count($entries)?> contestants · <?=count($judges)?> judges</p></header><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><section class="card result-card shadow-sm mb-4"><div class="card-body"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><h2 class="h4 mb-1">Calculated Official Ranking</h2><p class="text-muted mb-0">Review placement and combined total before inspecting each judge.</p></div><a class="btn btn-outline-dark" target="_blank" rel="noopener" href="judge-sheet.php?id=<?=$id?>">Print Detailed Results</a></div><div class="table-responsive mt-3"><table class="table table-striped align-middle mb-0"><thead><tr><th>Place</th><th>No.</th><th>Contestant</th><th>Combined Score</th></tr></thead><tbody><?php foreach($results as $result):?><tr><td class="fs-5 fw-bold">#<?=(int)$result['placement']?></td><td><?=(int)$result['bib_number']?></td><td class="fw-bold"><?=e($result['display_name'])?></td><td><?=e(dcReviewNumber((float)$result['total_score']))?></td></tr><?php endforeach;?></tbody></table></div></div></section><h2 class="h4">Judge Scores &amp; Private Comments</h2><p class="alert alert-warning"><strong>Confidential:</strong> comments on this page are available only to Super Admin and are excluded from public results and projection.</p><?php foreach($entries as $entry):$entryId=(int)$entry['id'];?><section class="card shadow-sm mb-4"><div class="card-body"><h3 class="h5">No. <?=(int)$entry['bib_number']?> · <?=e($entry['display_name'])?></h3><div class="row g-3 mt-1"><?php foreach($judges as $judge):$judgeId=(int)$judge['id'];$subtotal=0.0;?><div class="col-xl-6"><article class="judge-block"><div class="judge-head"><strong>J<?=(int)$judge['judge_order']?> · <?=e($judge['judge_name'])?></strong><?=$judge['is_chief']?' · Chief Judge':''?></div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><?php foreach($criteria as $criterion):?><th><?=e($criterion['criterion_name'])?></th><?php endforeach;?><th>Subtotal</th></tr></thead><tbody><tr><?php foreach($criteria as $criterion):$value=$marks[$entryId][$judgeId][(int)$criterion['id']]??null;if($value!==null)$subtotal+=(float)$value;?><td><?=$value===null?'—':e(dcReviewNumber((float)$value))?></td><?php endforeach;?><td class="fw-bold"><?=e(dcReviewNumber($subtotal))?></td></tr></tbody></table></div><?php if(isset($comments[$entryId][$judgeId])):?><div class="comment"><strong>Private comment</strong><br><?=e($comments[$entryId][$judgeId])?></div><?php else:?><div class="p-2 text-muted small">No private comment.</div><?php endif;?></article></div><?php endforeach;?></div></div></section><?php endforeach;?><?php if($pending):?><section class="card approval-dock"><div class="card-body"><form method="post" onsubmit="return confirm('Approve and publish this official result to permanent history? This does not reveal it on projection.')"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="review_confirmed" value="1" id="reviewConfirmed" required><label class="form-check-label fw-bold" for="reviewConfirmed">I reviewed the ranking, every judge score and all private comments.</label></div><div class="row g-2"><div class="col"><input class="form-control" name="approval_notes" placeholder="Super Admin approval notes (optional)"></div><div class="col-auto"><button class="btn btn-success btn-lg">Approve &amp; Publish Official Result</button></div></div><small class="text-muted d-block mt-2">This writes the approved placements to permanent history. Projection reveal remains locked and separately controlled.</small></form></div></section><?php else:?><div class="alert alert-success">This result is already approved. No further approval action is available.</div><?php endif;?></main></body></html>
